"""id — faith_b."""

T = {
"faith_071": ("Apa arti nama Allah «As-Salam»?", ["Yang Mahasejahtera, bebas dari segala kekurangan", "Yang Maha Pencipta", "Yang Maha Pemberi Rezeki", "Yang Mahaperkasa"], "As-Salam termasuk nama yang disebut di akhir surah Al-Hasyr: Dia Mahasejahtera, bebas dari segala kekurangan."),
"faith_072": ("Sifat apa yang ayat 59:22 sandingkan dengan nama Allah, tepat setelah «tidak ada tuhan selain Dia»?", ["Yang mengetahui yang gaib dan yang nyata, Yang Maha Pengasih", "Raja dan Pejuang", "Yang Kaya dan Dermawan", "Yang Kuat dan Cepat"], "«Dialah Allah, tidak ada tuhan selain Dia, Yang Mengetahui yang gaib dan yang nyata. Dialah Yang Maha Pengasih, Maha Penyayang»."),
"faith_073": ("Apa yang Al-Qur'an perintahkan dilakukan dengan nama-nama terindah Allah?", ["Berdoa kepada-Nya dengan nama-nama itu", "Hanya menghitungnya", "Menuliskannya di pintu", "Mendiamkannya"], "«Dan Allah memiliki nama-nama yang terbaik: maka berdoalah kepada-Nya dengan nama-nama itu»."),
"faith_074": ("Bagaimana surah Taha memperkenalkan nama-nama Allah?", ["«Allah! Tidak ada tuhan selain Dia. Dia memiliki nama-nama yang terbaik»", "«Nama-Nya tersembunyi»", "«Nama-Nya tak terhitung»", "«Nama-Nya sembilan»"], "«Allah! Tidak ada tuhan selain Dia. Dia memiliki nama-nama yang terbaik»."),
"faith_075": ("Ungkapan apa yang Al-Qur'an pakai untuk menafikan keserupaan dengan Allah?", ["«Tidak ada sesuatu pun yang serupa dengan Dia; dan Dialah Yang Maha Mendengar, Maha Melihat»", "«Dia raja terbesar»", "«Dia seperti cahaya»", "«Tak seorang pun melihat-Nya»"], "«Tidak ada sesuatu pun yang serupa dengan Dia; dan Dialah Yang Maha Mendengar, Maha Melihat»."),
"faith_076": ("Apa yang Ayat Kursi katakan tentang kantuk dan tidur?", ["Tidak mengantuk dan tidak tidur", "Dia tidur di malam hari", "Dia beristirahat pada hari ketujuh", "Dia berjaga selang sehari"], "«Tidak mengantuk dan tidak tidur»."),
"faith_077": ("Apa yang Al-Qur'an katakan tentang pengetahuan Allah atas sehelai daun yang jatuh?", ["Tidak sehelai daun pun gugur melainkan Dia mengetahuinya", "Dia mengetahuinya kemudian", "Malaikat memberitahu-Nya", "Itu tidak dicatat"], "«Dan pada-Nya kunci-kunci semua yang gaib… tidak ada sehelai daun pun yang gugur melainkan Dia mengetahuinya»."),
"faith_078": ("Dari apa Allah lebih dekat kepada manusia menurut surah Qaf?", ["Dari urat lehernya", "Dari bayangannya", "Dari suaranya", "Dari rumahnya"], "«Dan sungguh, Kami telah menciptakan manusia dan mengetahui apa yang dibisikkan oleh jiwanya; dan Kami lebih dekat kepadanya daripada urat lehernya»."),
"faith_079": ("Bagaimana Al-Qur'an menggambarkan malaikat penjaga neraka?", ["Mereka tidak mendurhakai Allah dan mengerjakan apa yang diperintahkan", "Sebagian ragu", "Mereka tidur", "Mereka memilih"], "«…malaikat-malaikat yang kasar dan keras, yang tidak durhaka kepada Allah terhadap apa yang Dia perintahkan kepada mereka dan selalu mengerjakan apa yang diperintahkan»."),
"faith_080": ("Bagaimana Al-Qur'an menggambarkan malaikat terhadap firman Allah?", ["Mereka tidak mendahului-Nya dengan perkataan dan mengerjakan perintah-Nya", "Mereka membantah perintah-Nya", "Mereka memutuskan sendiri", "Mereka selalu diam"], "«Sebaliknya mereka adalah hamba-hamba yang dimuliakan: mereka tidak mendahului-Nya dengan perkataan dan mereka mengerjakan perintah-Nya»."),
"faith_081": ("Malaikat manakah yang Al-Qur'an sebut menurunkan wahyu ke dalam hati Nabi ﷺ?", ["Jibril", "Mikail", "Israfil", "Malik"], "«Katakanlah: barang siapa menjadi musuh Jibril… dialah yang menurunkannya ke dalam hatimu dengan izin Allah»."),
"faith_082": ("Malaikat lain manakah yang disebut bersama Jibril dalam surah Al-Baqarah?", ["Mikail", "Israfil", "Ridwan", "Munkar"], "«Barang siapa menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya, Jibril, dan Mikail…»"),
"faith_083": ("Rukun iman apa yang disebut ayat 4:136?", ["Allah, Rasul-Nya, Kitab yang diturunkan, dan Kitab-kitab sebelumnya", "Hanya Kitab", "Hanya para nabi", "Hanya para malaikat"], "«Wahai orang-orang yang beriman! Tetaplah beriman kepada Allah dan Rasul-Nya dan kepada Kitab yang diturunkan kepada Rasul-Nya, serta Kitab yang diturunkan sebelumnya»."),
"faith_084": ("Kitab apa yang Al-Qur'an sebut diberikan kepada Daud?", ["Zabur", "Taurat", "Injil", "Suhuf Ibrahim"], "«…dan Kami berikan Zabur kepada Daud»."),
"faith_085": ("Surah manakah yang bernama jin, yang mendengarkan Al-Qur'an lalu beriman?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Katakanlah: telah diwahyukan kepadaku bahwa sekumpulan jin telah mendengarkan lalu berkata: kami telah mendengarkan bacaan yang menakjubkan»."),
"faith_086": ("Untuk apa jin dan manusia diciptakan menurut surah Az-Zariyat?", ["Agar mereka beribadah kepada-Nya", "Untuk memakmurkan bumi", "Untuk membangun", "Untuk berselisih"], "«Aku tidak menciptakan jin dan manusia melainkan agar mereka beribadah kepada-Ku»."),
"faith_087": ("Apa yang Al-Qur'an katakan tentang setiap jiwa dan kematian?", ["Setiap jiwa akan merasakan mati", "Sebagian jiwa tidak mati", "Kematian itu keraguan", "Kematian itu tidur tanpa akhir"], "«Setiap yang bernyawa akan merasakan mati; dan hanya pada hari kiamat sajalah diberikan dengan sempurna balasanmu»."),
"faith_088": ("Dalam keadaan bagaimana manusia keluar menurut surah Az-Zalzalah, untuk diperlihatkan amal mereka?", ["Dalam keadaan berkelompok-kelompok terpisah", "Semua bersama dalam satu barisan", "Dalam keadaan tertidur", "Diam dan tak terlihat"], "«Pada hari itu manusia keluar dari kuburnya dalam keadaan berkelompok-kelompok, untuk diperlihatkan kepada mereka amal perbuatannya»."),
"faith_089": ("Bagaimana surah Al-Kahfi menggambarkan catatan amal pada hari kiamat?", ["Tidak meninggalkan yang kecil maupun yang besar melainkan mencatatnya", "Hanya mencatat yang besar", "Ia dihapus", "Ia ditulis manusia"], "«Mereka berkata: “Betapa celaka kami! Kitab apakah ini, tidak meninggalkan yang kecil dan tidak pula yang besar, melainkan mencatat semuanya?”»"),
"faith_090": ("Apa yang Al-Qur'an katakan tentang anggota tubuh pada hari kiamat?", ["Tangan akan berbicara dan kaki akan bersaksi", "Mereka tetap bisu", "Mereka disembunyikan", "Mereka diubah"], "«Pada hari ini Kami tutup mulut mereka; tangan mereka akan berkata kepada Kami dan kaki mereka akan memberi kesaksian terhadap apa yang dahulu mereka kerjakan»."),
"faith_091": ("Bagaimana Al-Qur'an menyifati salat dari segi waktunya?", ["Kewajiban yang ditentukan waktunya", "Bebas kapan saja", "Sekali sepekan", "Hanya pada malam hari"], "«Sungguh, salat itu adalah kewajiban yang ditentukan waktunya atas orang-orang yang beriman»."),
"faith_092": ("Dari apa salat mencegah menurut surah Al-'Ankabut?", ["Dari perbuatan keji dan mungkar", "Dari kelaparan", "Dari penyakit", "Dari perjalanan"], "«Dan laksanakanlah salat: sesungguhnya salat itu mencegah dari perbuatan keji dan mungkar»."),
"faith_093": ("Salat manakah yang Al-Qur'an sebut secara khusus sebagai «salat wustha»?", ["Disebut namanya tanpa ditentukan, dalam perintah memelihara salat", "Hanya salat subuh", "Hanya salat magrib", "Salat Jumat"], "«Peliharalah semua salat dan salat wustha, dan laksanakanlah salat karena Allah dengan khusyuk»."),
"faith_094": ("Untuk tujuan apa Al-Qur'an memerintahkan salat dalam surah Taha?", ["Untuk mengingat Allah", "Untuk beristirahat", "Untuk berkumpul", "Untuk menghitung jam"], "«Sungguh, Aku ini Allah: tidak ada tuhan selain Aku. Maka sembahlah Aku dan laksanakanlah salat untuk mengingat Aku»."),
"faith_095": ("Sifat salat apa yang membuka daftar orang beriman yang beruntung dalam Al-Mu'minun?", ["Khusyuk dalam salat", "Panjangnya", "Cepatnya", "Jumlahnya"], "«Sungguh beruntung orang-orang yang beriman: yaitu orang yang khusyuk dalam salatnya»."),
"faith_096": ("Salat manakah yang surah Al-Isra sifati sebagai «disaksikan» (masyhudah)?", ["Bacaan fajar", "Salat magrib", "Salat zuhur", "Salat Jumat"], "«Laksanakanlah salat sejak matahari tergelincir sampai gelapnya malam, dan bacaan fajar: sesungguhnya bacaan fajar itu disaksikan»."),
"faith_097": ("Dengan dua hal apa Al-Qur'an memerintahkan memohon pertolongan?", ["Dengan sabar dan salat", "Dengan kekuatan dan kekayaan", "Dengan perjalanan dan istirahat", "Dengan diam dan menyendiri"], "«Wahai orang-orang yang beriman! Mohonlah pertolongan dengan sabar dan salat: sungguh Allah beserta orang-orang yang sabar»."),
"faith_098": ("Berapa rakaat salat fardu Zuhur?", ["Empat", "Dua", "Tiga", "Lima"], "Zuhur, Asar, dan Isya masing-masing empat rakaat fardu; para ulama mazhab sepakat dalam hal ini."),
"faith_099": ("Manakah salat fardu terakhir dalam sehari?", ["Isya", "Subuh", "Magrib", "Asar"], "Urutannya: Subuh, Zuhur, Asar, Magrib, Isya."),
"faith_100": ("Apa nama gerakan bersujud dalam salat?", ["Sujud", "Rukuk", "Kiam", "Tasyahud"], "Kiam adalah berdiri, rukuk adalah membungkuk, sujud adalah bersujud, dan tasyahud adalah duduk membaca syahadat."),
"faith_101": ("Apa yang Al-Qur'an tetapkan bagi orang sakit atau musafir pada bulan Ramadan?", ["Mengganti puasa pada hari-hari lain sejumlah yang ditinggalkan", "Tidak ada ketentuan", "Kewajiban ganda", "Puasa selamanya"], "«Maka barang siapa di antara kamu sakit atau dalam perjalanan, wajib mengganti sebanyak hari yang ditinggalkan pada hari-hari yang lain»."),
"faith_102": ("Tujuan apa yang Al-Qur'an berikan bagi puasa yang diwajibkan?", ["Mencapai takwa", "Menurunkan berat badan", "Berhemat", "Beristirahat"], "«Diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang sebelum kamu, agar kamu bertakwa»."),
"faith_103": ("Apa jawaban Allah di tengah ayat-ayat puasa bagi yang bertanya tentang kedekatan-Nya?", ["«Aku dekat: Aku kabulkan permohonan orang yang berdoa kepada-Ku»", "«Tunggulah malam»", "«Tanyalah para malaikat»", "«Carilah di kejauhan»"], "«Dan apabila hamba-hamba-Ku bertanya kepadamu tentang Aku, maka sesungguhnya Aku dekat: Aku kabulkan permohonan orang yang berdoa apabila dia berdoa kepada-Ku»."),
"faith_104": ("Berapa golongan penerima zakat yang Al-Qur'an sebutkan?", ["Delapan", "Tiga", "Lima", "Dua belas"], "«Sesungguhnya zakat itu hanyalah untuk orang fakir, orang miskin, amil zakat, yang dilunakkan hatinya, untuk memerdekakan hamba sahaya, untuk membebaskan orang yang berutang, untuk jalan Allah, dan untuk orang yang sedang dalam perjalanan»."),
"faith_105": ("Pengaruh apa yang Al-Qur'an nisbatkan pada zakat yang diambil dari harta?", ["Ia menyucikan dan menumbuhkan", "Ia memiskinkan", "Ia hanya simbol", "Ia menggantikan salat"], "«Ambillah zakat dari harta mereka, guna membersihkan dan menyucikan mereka»."),
"faith_106": ("Dua kewajiban apa yang paling sering Al-Qur'an sandingkan?", ["Salat dan zakat", "Puasa dan perjalanan", "Haji dan perdagangan", "Membaca dan menulis"], "«Dan laksanakanlah salat dan tunaikanlah zakat; segala kebaikan yang kamu kerjakan untuk dirimu akan kamu dapatkan di sisi Allah»."),
"faith_107": ("Apa yang sampai kepada Allah dalam kurban menurut Al-Qur'an?", ["Bukan daging maupun darahnya, melainkan ketakwaan orang beriman", "Hanya dagingnya", "Hanya darahnya", "Jumlah hewannya"], "«Daging dan darahnya itu sekali-kali tidak akan sampai kepada Allah, tetapi yang sampai kepada-Nya adalah ketakwaan kamu»."),
"faith_108": ("Apa sebaik-baik bekal untuk haji menurut Al-Qur'an?", ["Takwa", "Emas", "Perbekalan makanan", "Kendaraan"], "«Dan berbekallah; sesungguhnya sebaik-baik bekal adalah takwa»."),
"faith_109": ("Ibadah apa yang Al-Qur'an sebut di sekeliling Baitul Atiq?", ["Tawaf", "Berlari di padang pasir", "Menaiki bukit", "Berpuasa di sana"], "«…dan hendaklah mereka melakukan tawaf di sekeliling Baitul Atiq»."),
"faith_110": ("Di mana Al-Qur'an memerintahkan berzikir kepada Allah setelah bertolak dari Arafah?", ["Di Masy'aril Haram, di Muzdalifah", "Di gunung Uhud", "Di Quba", "Di Thaif"], "«Maka apabila kamu bertolak dari Arafah, berzikirlah kepada Allah di Masy'aril Haram»."),
"faith_111": ("Tobat macam apa yang Al-Qur'an minta dari orang beriman?", ["Tobat yang tulus (taubat nasuha)", "Tobat tertulis", "Tobat di depan umum", "Tobat tahunan"], "«Wahai orang-orang yang beriman! Bertobatlah kepada Allah dengan tobat yang semurni-murninya»."),
"faith_112": ("Apa yang surah Asy-Syura katakan tentang diterimanya tobat?", ["Dialah yang menerima tobat hamba-hamba-Nya dan memaafkan kesalahan", "Tobat tidak diterima", "Diperlukan perantara", "Harus menunggu setahun"], "«Dan Dialah yang menerima tobat dari hamba-hamba-Nya dan memaafkan kesalahan-kesalahan, dan mengetahui apa yang kamu kerjakan»."),
"faith_113": ("Apa yang dilakukan orang yang Al-Qur'an puji setelah melakukan kesalahan?", ["Mereka mengingat Allah lalu memohon ampunan", "Mereka lari", "Mereka diam", "Mereka menyalahkan orang lain"], "«Dan orang-orang yang apabila mengerjakan perbuatan keji atau menzalimi diri sendiri, mereka mengingat Allah lalu memohon ampunan atas dosa-dosa mereka»."),
"faith_114": ("Seberapa sering Al-Qur'an memerintahkan mengingat Allah dalam surah Al-Ahzab?", ["Sebanyak-banyaknya, pagi dan petang", "Sekali setahun", "Sekali sepekan", "Hanya dalam perjalanan"], "«Wahai orang-orang yang beriman! Ingatlah Allah dengan zikir yang sebanyak-banyaknya, dan bertasbihlah kepada-Nya pada waktu pagi dan petang»."),
"faith_115": ("Tentang apa «orang-orang yang berakal» merenung di akhir surah Ali 'Imran?", ["Tentang penciptaan langit dan bumi, dalam setiap keadaan", "Tentang panen", "Tentang kafilah", "Tentang silsilah"], "«Yaitu orang-orang yang mengingat Allah sambil berdiri, duduk, atau dalam keadaan berbaring, dan mereka memikirkan tentang penciptaan langit dan bumi»."),
"faith_116": ("Apa yang Al-Qur'an perintahkan setelah suatu keputusan diambil?", ["Bertawakal kepada Allah", "Menunggu tanda", "Bertanya kepada peramal", "Mengurungkannya"], "«Kemudian, apabila engkau telah membulatkan tekad, maka bertawakallah kepada Allah: sungguh Allah mencintai orang yang bertawakal»."),
"faith_117": ("Kepada siapa surah Asy-Syarh mengarahkan harapan, setelah pekerjaan selesai?", ["Kepada Tuhannya", "Kepada istirahat", "Kepada keluarga", "Kepada manusia"], "«Maka apabila engkau telah selesai, tetaplah bekerja keras; dan hanya kepada Tuhanmu berharaplah»."),
"faith_118": ("Dengan apa surah Al-Hadid mengumpamakan kehidupan dunia?", ["Dengan hujan yang tanamannya mengagumkan, lalu menguning dan menjadi hancur", "Dengan perjalanan panjang", "Dengan sebuah gunung", "Dengan samudra"], "«Ketahuilah bahwa kehidupan dunia itu hanyalah permainan dan kelalaian… seperti hujan yang tanamannya mengagumkan para petani; kemudian menguning lalu hancur»."),
"faith_119": ("Apa yang Al-Qur'an nyatakan lebih baik daripada harta dan anak, perhiasan dunia?", ["Amal kebajikan yang kekal", "Emas", "Ketenaran", "Tanah"], "«Harta dan anak-anak adalah perhiasan kehidupan dunia; tetapi amal kebajikan yang terus-menerus adalah lebih baik pahalanya di sisi Tuhanmu»."),
"faith_120": ("Pertanyaan apa yang Al-Qur'an ajukan tentang tujuan penciptaan manusia?", ["«Apakah kamu mengira bahwa Kami menciptakan kamu main-main?»", "«Siapa yang menamaimu?»", "«Ke mana kamu akan pergi?»", "«Berapa jumlahmu?»"], "«Maka apakah kamu mengira bahwa Kami menciptakan kamu main-main, dan bahwa kamu tidak akan dikembalikan kepada Kami?»"),
"faith_121": ("Janji apa yang Al-Qur'an berikan bagi yang mengingat Allah?", ["«Ingatlah kepada-Ku, niscaya Aku ingat kepadamu»", "«Kamu akan kaya»", "«Kamu akan panjang umur»", "«Kamu akan bepergian»"], "«Maka ingatlah kepada-Ku, niscaya Aku ingat kepadamu. Bersyukurlah kepada-Ku dan janganlah kamu ingkar»."),
"faith_122": ("Kepada siapa Al-Qur'an memerintahkan perselisihan dikembalikan?", ["Kepada Allah dan Rasul ﷺ", "Kepada para tetua", "Kepada pasar", "Kepada para penyair"], "«Kemudian jika kamu berbeda pendapat tentang sesuatu, maka kembalikanlah kepada Allah dan Rasul, jika kamu beriman kepada Allah dan hari akhir»."),
"faith_123": ("Bagaimana surah Al-Anfal menggambarkan hati orang beriman saat Allah disebut?", ["Hati mereka bergetar dan iman mereka bertambah dengan bacaan ayat", "Mengeras", "Tertidur", "Melupakan"], "«Sesungguhnya orang-orang yang beriman itu ialah mereka yang apabila disebut nama Allah gemetar hatinya, dan apabila dibacakan ayat-ayat-Nya bertambah imannya»."),
"faith_124": ("Apa yang Al-Qur'an perintahkan agar dipersembahkan seluruhnya kepada Tuhan semesta alam?", ["Salat, ibadah, hidup, dan mati", "Perdagangan", "Panen", "Perjalanan"], "«Katakanlah: sesungguhnya salatku, ibadahku, hidupku, dan matiku hanyalah untuk Allah, Tuhan seluruh alam»."),
"faith_125": ("Syarat apa yang surah Al-Bayyinah tetapkan bagi ibadah yang diperintahkan?", ["Menyembah Allah dengan ikhlas menaati-Nya semata-mata", "Beribadah di depan umum", "Beribadah secara tertulis", "Beribadah hanya berjamaah"], "«Padahal mereka hanya diperintah menyembah Allah dengan ikhlas menaati-Nya semata-mata, dan melaksanakan salat serta menunaikan zakat»."),
"faith_126": ("Apa yang Al-Qur'an gambarkan mengalir di surga yang dijanjikan bagi orang bertakwa?", ["Sungai-sungai", "Jalan-jalan", "Jembatan-jembatan", "Sumur-sumur"], "Al-Qur'an berulang kali menggambarkan surga «yang mengalir di bawahnya sungai-sungai»."),
"faith_127": ("Apa yang Al-Qur'an katakan tentang yang disembunyikan bagi orang beriman sebagai balasan?", ["Tidak seorang pun tahu apa yang disembunyikan untuk mereka sebagai penyejuk mata", "Semuanya digambarkan rinci", "Berupa kekayaan", "Berupa kerajaan"], "«Maka tidak seorang pun mengetahui apa yang disembunyikan untuk mereka, yaitu bermacam nikmat yang menyedapkan pandangan, sebagai balasan atas apa yang mereka kerjakan»."),
"faith_128": ("Apa yang Al-Qur'an janjikan bagi orang yang berbuat baik, di samping balasan terbaik?", ["Tambahan (ziyadah)", "Penundaan", "Kerajaan", "Sebuah kitab"], "«Bagi orang-orang yang berbuat baik ada pahala yang terbaik dan tambahannya»."),
"faith_129": ("Bagaimana Al-Qur'an menggambarkan sambutan bagi orang bertakwa di pintu surga?", ["«Salam sejahtera bagimu! Kamu telah baik: masuklah untuk kekal di dalamnya»", "Dalam diam", "Setelah pengadilan panjang", "Satu per satu tanpa kata"], "«Dan penjaga-penjaganya berkata kepada mereka: “Salam sejahtera bagimu, berbahagialah kamu! Maka masuklah, kamu kekal di dalamnya”»."),
"faith_130": ("Kepada apa Al-Qur'an memerintahkan bersegera dalam surah Ali 'Imran?", ["Kepada ampunan Tuhan dan surga yang luasnya seluas langit dan bumi", "Kepada pasar", "Kepada perjalanan", "Kepada kekayaan"], "«Dan bersegeralah kamu kepada ampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi, yang disediakan bagi orang-orang yang bertakwa»."),
"faith_131": ("Tanggung jawab apa yang Al-Qur'an bebankan pada orang beriman terhadap keluarganya?", ["Menjaga mereka dan dirinya dari api neraka", "Menjadikan mereka kaya", "Mengajari mereka bahasa", "Mengajak mereka bepergian"], "«Wahai orang-orang yang beriman! Peliharalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu»."),
"faith_132": ("Bagaimana ayat 2:177 mendefinisikan kebajikan sejati (al-birr)?", ["Beriman kepada Allah, hari akhir, malaikat, Kitab, dan para nabi, serta memberikan harta", "Menghadapkan wajah ke timur atau barat", "Hanya berpuasa", "Bepergian"], "«Kebajikan itu bukanlah menghadapkan wajahmu ke arah timur dan barat, tetapi kebajikan itu ialah beriman kepada Allah, hari akhir, malaikat, Kitab, dan nabi-nabi»."),
"faith_133": ("Siapa yang akan melihat amal yang dikerjakan menurut surah At-Taubah?", ["Allah, Rasul-Nya ﷺ, dan orang-orang beriman", "Tidak seorang pun", "Hanya malaikat", "Para raja"], "«Dan katakanlah: bekerjalah kamu, maka Allah akan melihat pekerjaanmu, begitu juga Rasul-Nya dan orang-orang mukmin»."),
"faith_134": ("Dengan pernyataan apa surah Al-Ikhlas berakhir?", ["«Dan tidak ada sesuatu pun yang setara dengan Dia»", "«Dia yang terbesar»", "«Dia dekat»", "«Dia yang pertama»"], "«Dan tidak ada sesuatu pun yang setara dengan Dia»."),
"faith_135": ("Empat nama apa yang surah Al-Hadid himpun dalam satu ayat?", ["Yang Awal, Yang Akhir, Yang Zahir, dan Yang Batin", "Raja, Yang Mahasuci, Yang Mahasejahtera, Yang Maha Memberi Keamanan", "Pencipta, Yang Mengadakan, Yang Membentuk, Yang Mahabijaksana", "Yang Mahahidup, Yang Terus Menerus Mengurus, Yang Maha Mendengar, Yang Maha Melihat"], "«Dialah Yang Awal, Yang Akhir, Yang Zahir, dan Yang Batin; dan Dia Maha Mengetahui segala sesuatu»."),
"faith_136": ("Nama apa yang disebut di akhir surah Al-Hasyr setelah «Al-Malik»?", ["Al-Quddus, As-Salam, Al-Mu'min, Al-Muhaimin", "Al-Khaliq, Al-Mushawwir", "Al-Ghafur, Ar-Rahim", "As-Sami', Al-Bashir"], "«Dialah Allah, Yang tiada tuhan selain Dia, Al-Malik, Al-Quddus, As-Salam, Al-Mu'min, Al-Muhaimin, Al-'Aziz…»"),
"faith_137": ("Apa sebutan untuk kalimat «Tidak ada tuhan selain Allah, Muhammad utusan-Nya»?", ["Syahadat", "Basmalah", "Takbir", "Tasmiyah"], "Syahadat adalah kalimat pertama Islam dan rukunnya yang pertama."),
"faith_138": ("Apa sebutan untuk kalimat «Allahu akbar»?", ["Takbir", "Tahlil", "Tasbih", "Tahmid"], "Takbir adalah «Allahu akbar», tasbih «subhanallah», tahmid «alhamdulillah», dan tahlil «la ilaha illallah»."),
"faith_139": ("Apa sebutan untuk kalimat «Dengan nama Allah Yang Maha Pengasih, Maha Penyayang»?", ["Basmalah", "Hamdalah", "Hauqalah", "Istirja'"], "Basmalah membuka semua surah kecuali satu; hauqalah adalah «la haula wa la quwwata illa billah»."),
"faith_140": ("Kalimat apa yang Al-Qur'an ajarkan ketika musibah datang?", ["«Sesungguhnya kami milik Allah dan kepada-Nya kami kembali»", "«Mengapa aku?»", "«Ini akan berlalu»", "«Begitulah nasib manusia»"], "«Yaitu orang-orang yang apabila ditimpa musibah mereka berkata: “Sesungguhnya kami milik Allah dan kepada-Nyalah kami kembali”»."),
"faith_141": ("Apa yang Al-Qur'an perintahkan diucapkan saat menyatakan akan melakukan sesuatu besok?", ["«Insya Allah» (jika Allah menghendaki)", "«Sudah dijanjikan»", "«Pasti»", "«Aku bersumpah»"], "«Dan jangan sekali-kali engkau mengatakan terhadap sesuatu: “Aku pasti melakukan itu besok”, kecuali dengan mengatakan: “Insya Allah”»."),
"faith_142": ("Pengetahuan apa yang Al-Qur'an khususkan bagi Allah di akhir surah Luqman?", ["Hari kiamat, hujan, apa yang ada dalam rahim, apa yang diperoleh esok, dan di bumi mana seseorang mati", "Jumlah bintang", "Nama para raja", "Hitungan hari"], "«Sesungguhnya hanya di sisi Allah ilmu tentang hari kiamat; dan Dialah yang menurunkan hujan dan mengetahui apa yang ada dalam rahim. Dan tidak ada seorang pun yang dapat mengetahui apa yang akan dikerjakannya besok, dan tidak ada seorang pun yang dapat mengetahui di bumi mana dia akan mati»."),
"faith_143": ("Apa yang Al-Qur'an katakan tentang ajal yang ditetapkan bagi setiap umat?", ["Bila tiba, tidak dapat diundur atau dimajukan sesaat pun", "Ia dapat diubah", "Allah tidak mengetahuinya", "Ia bergantung pada raja"], "«Setiap umat mempunyai ajal: apabila ajalnya tiba, mereka tidak dapat meminta penundaan atau percepatan sesaat pun»."),
"faith_144": ("Apa yang Al-Qur'an janjikan bagi yang beramal saleh, laki-laki atau perempuan, dalam keadaan beriman?", ["Kehidupan yang baik dan balasan sesuai amal terbaik mereka", "Kekayaan", "Kekuasaan", "Ketenaran"], "«Barang siapa mengerjakan kebajikan, baik laki-laki maupun perempuan, dalam keadaan beriman, maka pasti akan Kami berikan kepadanya kehidupan yang baik»."),
"faith_145": ("Perbedaan apa yang Al-Qur'an tetapkan antara «Islam» dan «iman» dalam surah Al-Hujurat?", ["Mengatakan «kami telah berserah diri» belumlah iman masuk ke dalam hati", "Keduanya kata yang sama", "Iman selalu lebih dahulu", "Islam hanya untuk ulama"], "«Orang-orang Arab Badui berkata: “Kami telah beriman”. Katakanlah: “Kamu belum beriman, tetapi katakanlah: kami telah berislam, karena iman belum masuk ke dalam hatimu”»."),
"faith_146": ("Kaidah apa yang surah Al-Ma'idah tetapkan tentang nyawa satu orang?", ["Siapa membunuh satu jiwa seakan membunuh seluruh manusia; siapa memelihara satu jiwa seakan memelihara semuanya", "Setiap nyawa dihitung satu", "Hanya kerabat yang dihitung", "Hanya jumlah yang dihitung"], "«Barang siapa membunuh seseorang, bukan karena orang itu membunuh orang lain atau membuat kerusakan di bumi, maka seakan-akan dia telah membunuh semua manusia; dan barang siapa memelihara kehidupan seorang manusia, maka seakan-akan dia telah memelihara kehidupan semua manusia»."),
"faith_147": ("Berapa kali lipat Al-Qur'an melipatgandakan balasan kebaikan?", ["Sepuluh kali lipat", "Dua kali lipat", "Seratus kali lipat", "Tidak dilipatgandakan"], "«Barang siapa berbuat kebaikan mendapat balasan sepuluh kali lipat amalnya; dan barang siapa berbuat kejahatan dibalas seimbang dengan kejahatannya»."),
"faith_148": ("Bagaimana surah Fatir menggambarkan hubungan manusia dengan Allah?", ["Merekalah yang fakir, dan Allah Mahakaya lagi Maha Terpuji", "Mereka sekutu-Nya", "Mereka tidak membutuhkan-Nya", "Mereka pemberi pinjaman kepada-Nya"], "«Wahai manusia! Kamulah yang memerlukan Allah; dan Allah Dialah Yang Mahakaya, Maha Terpuji»."),
"faith_149": ("Empat sifat apa yang menyelamatkan dari kerugian menurut surah Al-'Asr?", ["Iman, amal saleh, saling menasihati dalam kebenaran dan kesabaran", "Kekayaan, kekuatan, keindahan, tipu daya", "Diam, tidur, uzlah, puasa", "Perjalanan, dagang, tulisan, bacaan"], "«Demi masa! Sungguh, manusia berada dalam kerugian, kecuali orang-orang yang beriman dan mengerjakan kebajikan serta saling menasihati untuk kebenaran dan kesabaran»."),
"faith_150": ("Kepada apa orang beriman menyatakan iman dalam ayat kedua terakhir surah Al-Baqarah?", ["Kepada Allah, malaikat-Nya, kitab-kitab-Nya, dan rasul-rasul-Nya", "Kepada satu kitab", "Kepada satu malaikat", "Kepada leluhur mereka"], "«Rasul beriman kepada apa yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang beriman: semua beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, dan rasul-rasul-Nya»."),
}
